import{_ as t,o as a,c as s,ao as o}from"./chunks/framework.DcztfwHe.js";const g=JSON.parse('{"title":"Running benchmarks","description":"","frontmatter":{},"headers":[],"relativePath":"benchmarks.md","filePath":"benchmarks.md","lastUpdated":null}'),i={name:"benchmarks.md"};function d(n,e,c,r,h,l){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="Running-benchmarks" tabindex="-1">Running benchmarks <a class="header-anchor" href="#Running-benchmarks" aria-label="Permalink to &quot;Running benchmarks {#Running-benchmarks}&quot;">​</a></h1><p><a href="https://github.com/WaterLily-jl/WaterLily-Benchmarks/blob/main/benchmark.sh" target="_blank" rel="noreferrer"><code>benchmark.sh</code></a> runs every combination of Julia versions, WaterLily refs, backends and thread counts it is given. Each combination runs in a new Julia process that times all the requested cases and sizes and writes one JSON file per case. Nothing is shared between the processes but the files.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./benchmark.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;release 1.11&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -w</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;master my-branch&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Array CuArray&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;1 4&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">               -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;tgv jelly-biotsavart&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;6,7 5,6&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 25</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -ft</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Float32</span></span></code></pre></div><p>runs 2 Julia versions × 2 WaterLily refs × 3 backends (CPUx01, CPUx04, GPU-NVIDIA) = 12 processes, each timing <code>tgv</code> at <code>log2p = 6, 7</code> and <code>jelly-biotsavart</code> at <code>5, 6</code>.</p><h2 id="Options" tabindex="-1">Options <a class="header-anchor" href="#Options" aria-label="Permalink to &quot;Options {#Options}&quot;">​</a></h2><p>Lists are space-separated and quoted. When an option is given twice, the last value is used.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Option</th><th style="text-align:right;">Default</th><th style="text-align:right;">Meaning</th></tr></thead><tbody><tr><td style="text-align:right;"><code>-w</code>, <code>--waterlily</code></td><td style="text-align:right;">the current checkout</td><td style="text-align:right;">WaterLily refs (branches, tags or commit hashes), checked out in turn in <code>$WATERLILY_DIR</code></td></tr><tr><td style="text-align:right;"><code>-wd</code>, <code>--waterlily_dir</code></td><td style="text-align:right;"><code>$WATERLILY_DIR</code></td><td style="text-align:right;">the WaterLily.jl clone</td></tr><tr><td style="text-align:right;"><code>-v</code>, <code>--versions</code></td><td style="text-align:right;">the <code>julia</code> on the <code>PATH</code></td><td style="text-align:right;">Julia versions, run as <code>julia +&lt;version&gt;</code> (needs juliaup), e.g. <code>&quot;release 1.11&quot;</code></td></tr><tr><td style="text-align:right;"><code>-b</code>, <code>--backends</code></td><td style="text-align:right;"><code>&quot;Array CuArray&quot;</code></td><td style="text-align:right;"><code>Array</code> (CPU), <code>CuArray</code> (NVIDIA), <code>ROCArray</code> (AMD)</td></tr><tr><td style="text-align:right;"><code>-t</code>, <code>--threads</code></td><td style="text-align:right;"><code>4</code></td><td style="text-align:right;">CPU thread counts, used by <code>Array</code></td></tr><tr><td style="text-align:right;"><code>-c</code>, <code>--cases</code></td><td style="text-align:right;"><code>&quot;tgv jelly-biotsavart&quot;</code></td><td style="text-align:right;">cases, see <a href="./cases">Cases and checkpoints</a></td></tr><tr><td style="text-align:right;"><code>-p</code>, <code>--log2p</code></td><td style="text-align:right;">per case</td><td style="text-align:right;">sizes of each case, comma-separated, e.g. <code>&quot;6,7 5,6&quot;</code></td></tr><tr><td style="text-align:right;"><code>-s</code>, <code>--max_steps</code></td><td style="text-align:right;"><code>25</code></td><td style="text-align:right;">time steps per run</td></tr><tr><td style="text-align:right;"><code>-ft</code>, <code>--float_type</code></td><td style="text-align:right;"><code>Float32</code></td><td style="text-align:right;"><code>Float32</code> or <code>Float64</code></td></tr><tr><td style="text-align:right;"><code>-dev</code>, <code>--developed</code></td><td style="text-align:right;"><code>checkpoints</code></td><td style="text-align:right;">directory of the developed-flow checkpoints; <code>&quot;&quot;</code> times the startup transient instead</td></tr><tr><td style="text-align:right;"><code>-r</code>, <code>--repeats</code></td><td style="text-align:right;"><code>1</code></td><td style="text-align:right;">repetitions of the whole sweep, see <a href="/WaterLily-Benchmarks/previews/PR49/benchmarks#Repetitions">Repetitions</a></td></tr><tr><td style="text-align:right;"><code>-u</code>, <code>--update</code></td><td style="text-align:right;"><code>false</code></td><td style="text-align:right;">update the environment before each run, see <a href="/WaterLily-Benchmarks/previews/PR49/benchmarks#Updating-the-environment">Updating the environment</a></td></tr><tr><td style="text-align:right;"><code>-dd</code>, <code>--data_dir</code></td><td style="text-align:right;"><code>data/benchmark/</code></td><td style="text-align:right;">output directory</td></tr><tr><td style="text-align:right;"><code>-f</code>, <code>--force</code></td><td style="text-align:right;">off</td><td style="text-align:right;">run even if the <a href="/WaterLily-Benchmarks/previews/PR49/benchmarks#Machine-check">Machine check</a> fails</td></tr><tr><td style="text-align:right;"><code>-bs</code>, <code>--biotsavart</code></td><td style="text-align:right;">none</td><td style="text-align:right;">BiotSavartBCs refs paired with <code>-w</code>, see <a href="./biotsavart">BiotSavartBCs changes</a></td></tr><tr><td style="text-align:right;"><code>-bsd</code>, <code>--biotsavart_dir</code></td><td style="text-align:right;"><code>$BIOTSAVART_DIR</code></td><td style="text-align:right;">the BiotSavartBCs.jl clone used by <code>-bs</code></td></tr></tbody></table><h2 id="Cases,-sizes,-steps-and-types" tabindex="-1">Cases, sizes, steps and types <a class="header-anchor" href="#Cases,-sizes,-steps-and-types" aria-label="Permalink to &quot;Cases, sizes, steps and types {#Cases,-sizes,-steps-and-types}&quot;">​</a></h2><p><code>-p</code>, <code>-s</code> and <code>-ft</code> describe each case of <code>-c</code>: give either one value per case, in the same order, or a single value for all of them. An omitted option takes its default: the size of each case from the <code>DEF_LOG2P</code> map at the top of <code>benchmark.sh</code> (the sizes of its checkpoints, see <a href="./cases">Cases and checkpoints</a>), 25 steps and <code>Float32</code>. So</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./benchmark.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;tgv sphere&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -ft</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Float64</span></span></code></pre></div><p>runs <code>tgv</code> at <code>6,7</code> and <code>sphere</code> at <code>3,4</code>, both in <code>Float64</code>. A case missing from <code>DEF_LOG2P</code> needs <code>-p</code>. <code>log2p</code> sets the resolution: the length scale of the case is <code>2^log2p</code> cells, e.g. a <code>tgv</code> box of <code>64^3</code> cells at <code>log2p = 6</code>.</p><p>Each run starts from a checkpoint of a developed flow, <code>checkpoints/&lt;case&gt;_&lt;log2p&gt;_&lt;ftype&gt;.jld2</code>, and a missing checkpoint is an error. Pass <code>-dev &quot;&quot;</code> to time the startup transient instead, or <code>-dev &lt;dir&gt;</code> to read the checkpoints from another directory.</p><h2 id="Backends-and-threads" tabindex="-1">Backends and threads <a class="header-anchor" href="#Backends-and-threads" aria-label="Permalink to &quot;Backends and threads {#Backends-and-threads}&quot;">​</a></h2><p><code>Array</code> runs on the CPU once per thread count in <code>-t</code>. With 1 thread it uses WaterLily&#39;s SIMD backend (labelled <code>CPUx01</code>), and with more threads its KernelAbstractions backend (<code>CPUx04</code>, ...). <code>CuArray</code> and <code>ROCArray</code> run on the GPU (<code>GPU-NVIDIA</code>, <code>GPU-AMD</code>) in their own environments, which <code>benchmark.sh</code> makes on their first run; see <a href="./environments">Environments</a>. <code>benchmark.sh</code> writes the backend preference of each run into <code>LocalPreferences.toml</code>, so do not edit that file.</p><h2 id="Updating-the-environment" tabindex="-1">Updating the environment <a class="header-anchor" href="#Updating-the-environment" aria-label="Permalink to &quot;Updating the environment {#Updating-the-environment}&quot;">​</a></h2><p>With <code>-u true</code>, each run first develops WaterLily from <code>$WATERLILY_DIR</code> into the benchmark environment and updates the other packages (<code>Pkg.develop</code> and <code>Pkg.update</code>). A new clone does not need it: an environment without a <code>Manifest.toml</code> is installed on its first run (<code>Pkg.develop</code> only). Use it when the Julia version changes or when the WaterLily refs being compared have different dependencies. Without it, the environment stays as it is: WaterLily is developed from a path, so checking out another ref with <code>-w</code> is enough to run that code.</p><h2 id="Repetitions" tabindex="-1">Repetitions <a class="header-anchor" href="#Repetitions" aria-label="Permalink to &quot;Repetitions {#Repetitions}&quot;">​</a></h2><p><code>-r N</code> repeats the whole sweep <code>N</code> times, each benchmark in a new process, and reverses the order of the Julia versions and WaterLily refs on even repetitions. The files get an <code>_r&lt;n&gt;</code> suffix, and <code>compare.jl</code> merges the repetitions of a benchmark into one row (the <code>Reps</code> column). Use it when the state of the machine can change between processes, which is typical on laptops (clock speed, thermal and power limits); see <a href="/WaterLily-Benchmarks/previews/PR49/methodology#Noise-and-repetitions">Noise and repetitions</a>.</p><h2 id="Machine-check" tabindex="-1">Machine check <a class="header-anchor" href="#Machine-check" aria-label="Permalink to &quot;Machine check {#Machine-check}&quot;">​</a></h2><p>On Linux, <code>benchmark.sh</code> first checks that the machine will not distort the timings. It stops if a CPU is capped below its maximum frequency, giving the command that lifts the cap, or if fewer CPUs are available than the largest <code>-t</code> plus one (Julia also runs an interactive thread). It warns if turbo is off or the load average is above 1. <code>-f</code> runs anyway, e.g. on shared CI runners.</p><h2 id="Output" tabindex="-1">Output <a class="header-anchor" href="#Output" aria-label="Permalink to &quot;Output {#Output}&quot;">​</a></h2><p>Each process writes one JSON file per case into <code>&lt;data_dir&gt;/&lt;hostname&gt;_&lt;WaterLily hash&gt;/</code>, named</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;case&gt;_&lt;log2p&gt;_&lt;max_steps&gt;_&lt;ftype&gt;_&lt;backend&gt;_&lt;WaterLily hash&gt;_&lt;Julia version&gt;[_r&lt;n&gt;].json</span></span></code></pre></div><p>where <code>&lt;log2p&gt;</code> joins the sizes, e.g. <code>tgv_67_25_Float32_CPUx04_50cb584_1.11.5.json</code> for <code>log2p = 6,7</code>. A run with <code>-bs</code> uses <code>&lt;WaterLily hash&gt;+bs&lt;BiotSavartBCs hash&gt;</code> instead of the WaterLily hash. The files hold <code>BenchmarkTools</code> results whose tags describe the run, and <code>compare.jl</code> reads the tags, not the file names, so renaming a file is safe for <code>compare.jl</code> (but see <code>environments.toml</code> below).</p><p>Each data directory also keeps the environment of its runs, so that they can be reproduced:</p><ul><li><p><code>Manifest-&lt;Julia version&gt;-&lt;environment&gt;-&lt;hash&gt;.toml</code>: the resolved <code>Manifest.toml</code> of the run&#39;s environment (<code>cpu</code>, or <code>CUDA</code> and <code>AMDGPU</code> for the <a href="./environments">GPU environments</a>), one file per distinct Manifest. A package developed from a local clone, WaterLily from <code>$WATERLILY_DIR</code> or BiotSavartBCs with <code>-bs</code>, gets <code>path = &quot;&lt;package&gt;.jl&quot;</code> instead of the path on the machine, and the commit it ran from as <code>clone-commit</code> (with <code>clone-changes = true</code> if the clone had uncommitted changes). So the Manifest says which code ran, without paths of the machine it ran on.</p></li><li><p><code>environments.toml</code>: for each JSON file, its Manifest and the WaterLily preferences of the run (<code>LocalPreferences.toml</code>, the SIMD or KernelAbstractions backend).</p></li></ul><p>Two sweeps writing into the same data directory at the same time can lose entries of <code>environments.toml</code>; sweeps run one after the other are fine.</p>`,27)])])}const u=t(i,[["render",d]]);export{g as __pageData,u as default};
